import{_ as e,o as t,c as o,Q as a}from"./chunks/framework.b67c47e6.js";const s="/assets/viewer-list-selector.e336de62.svg",n="/assets/viewer-layout.67dc9e6f.svg",i="/assets/viewer-3d.26feb5c4.svg",r="/assets/viewer-clipping.4f4c20cc.svg",l="/assets/viewer-drawing.f197c711.svg",h="/assets/viewer-bom.28e7463e.svg",c="/assets/viewer-checklist.8ca48675.svg",d="/assets/viewer-multiwall.928a2c55.svg",g="/assets/viewer-new-issue.d18d9877.svg",p="/assets/viewer-employees.d52b31d9.svg",q=JSON.parse('{"title":"3D Viewer","description":"","frontmatter":{},"headers":[],"relativePath":"guide/viewer/index.md","filePath":"guide/viewer/index.md","lastUpdated":1790346505000}'),u={name:"guide/viewer/index.md"},m=a('<h1 id="_3d-viewer" tabindex="-1">3D Viewer <a class="header-anchor" href="#_3d-viewer" aria-label="Permalink to &quot;3D Viewer&quot;">​</a></h1><p>The Viewer is the main production interface in produuz.it. It displays 3D models and technical drawings of your constructibles (assemblies and modules), and provides tools for managing production checklists, issues, logistics, and more.</p><nav class="table-of-contents"><ul><li><a href="#accessing-the-viewer">Accessing the Viewer</a></li><li><a href="#the-list-on-the-left">The list on the left</a><ul><li><a href="#working-by-date">Working by date</a></li><li><a href="#working-by-project">Working by project</a></li><li><a href="#rows-of-the-list">Rows of the list</a></li></ul></li><li><a href="#layout">Layout</a></li><li><a href="#_3d-model">3D Model</a><ul><li><a href="#controls">Controls</a></li><li><a href="#selecting-parts">Selecting Parts</a></li><li><a href="#zone-selection">Zone Selection</a></li><li><a href="#advanced-tools">Advanced Tools</a></li></ul></li><li><a href="#technical-drawings">Technical Drawings</a></li><li><a href="#bill-of-materials-bom">Bill of Materials (BOM)</a><ul><li><a href="#part-list">Part List</a></li><li><a href="#unknown-parts">Unknown Parts</a></li><li><a href="#part-drawings">Part Drawings</a></li></ul></li><li><a href="#production-features">Production Features</a><ul><li><a href="#checklist">Checklist</a></li><li><a href="#multiwall-checklist">Multiwall Checklist</a></li><li><a href="#station-switching">Station Switching</a></li><li><a href="#issues">Issues</a></li><li><a href="#qr-code">QR Code</a></li><li><a href="#rfid-tag">RFID Tag</a></li><li><a href="#rack-logistics">Rack / Logistics</a></li></ul></li><li><a href="#who-is-working">Who is working</a></li><li><a href="#specifications-documents">Specifications &amp; Documents</a></li></ul></nav><h2 id="accessing-the-viewer" tabindex="-1">Accessing the Viewer <a class="header-anchor" href="#accessing-the-viewer" aria-label="Permalink to &quot;Accessing the Viewer&quot;">​</a></h2><p>Pick <strong>Prod</strong> in the mode toggle at the top of the left menu, then tap a constructible in the list. The mode toggle shows only the modes your account can use (<strong>Manage</strong>, <strong>Logistics</strong>, <strong>Prod</strong> and <strong>Delivery</strong>).</p><p>The Viewer has two modes, chosen in the list filter described below:</p><ul><li><strong>Production</strong> — For constructibles in production. Includes checklists, issues, QR, RFID and rack features.</li><li><strong>Design</strong> — For reviewing designs before production. Shows 3D models and drawings in read-only mode, without production tools. Production users do not have this mode.</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>If your company has <strong>Forced time registration in viewer</strong> switched on, production users see a <em>Constructible not started</em> message instead of the 3D model and the drawings until they start the panel from the checklist.</p></div><h2 id="the-list-on-the-left" tabindex="-1">The list on the left <a class="header-anchor" href="#the-list-on-the-left" aria-label="Permalink to &quot;The list on the left&quot;">​</a></h2><p>The left menu holds the queue: every constructible you can work on, in the order production follows. What sits above that list depends on how you are working.</p><h3 id="working-by-date" tabindex="-1">Working by date <a class="header-anchor" href="#working-by-date" aria-label="Permalink to &quot;Working by date&quot;">​</a></h3><p>With no project selected, and if your company works by date, the header shows the <strong>date selector</strong>: arrows for the previous and next day, and a dropdown with a calendar and two switches: <strong>Show delayed constructibles</strong>, to include constructibles that are late, and <strong>Max number of constructibles</strong>, to cap how many are listed at a time (between 5 and 50).</p><h3 id="working-by-project" tabindex="-1">Working by project <a class="header-anchor" href="#working-by-project" aria-label="Permalink to &quot;Working by project&quot;">​</a></h3><p>With a project selected, the header shows one control for everything that decides what the list holds. Closed, it tells you where you are:</p><ul><li>the phase on the top line and the batch on the bottom one, or <em>All phases</em> / <em>All batches</em> when nothing is filtered;</li><li>how many constructibles of what is listed are ready, out of the total;</li><li>a <code>×</code> to clear the filter in one tap, when a filter is set.</li></ul><p>The arrows step to the previous and next batch, continuing into the next phase when you reach the end of one.</p><p>Tapping the button opens it:</p><ul><li><strong>Production / Design</strong> at the top, for managers and admins. Production lists the panels and modules being built; Design lists the designs, read-only. In Design mode there are no batches, so the phase and batch list is not shown.</li><li><strong>All</strong> clears the filter.</li><li>Tap a <strong>phase</strong> to see its batches only.</li><li>Tap a <strong>batch</strong> to work on that batch alone.</li><li>Every row shows how many of its constructibles are ready. The count turns green once they all are, so a finished batch or phase is easy to spot. Batches with nothing in them are greyed out, marked <em>Empty</em>, and never count as finished.</li><li>The <strong>Show ready constructibles</strong> switch at the bottom shows or hides constructibles that are already finished. The menu stays open while you use it, so you can compare.</li></ul><p><img src="'+s+'" alt="The list filter, opened"></p><ol><li><strong>Production</strong> or <strong>Design</strong>, for managers and admins.</li><li>A finished phase: its count is green.</li><li>The batch you are working on.</li><li>A batch with nothing in it.</li><li>Show or hide the constructibles that are already finished.</li></ol><p>The constructible you currently have open always stays in the list, even when the filter would leave it out, so you never lose your place.</p><h3 id="rows-of-the-list" tabindex="-1">Rows of the list <a class="header-anchor" href="#rows-of-the-list" aria-label="Permalink to &quot;Rows of the list&quot;">​</a></h3><p>Each row shows the design name and revision, the position of the constructible in its batch (for example <strong>3</strong>/12), the first characters of its id and a <em>phase | batch</em> chip. Below that:</p><ul><li>a green <strong>Ready</strong> chip once the constructible is finished;</li><li>otherwise one numbered chip per station of your production line: outlined while the station has not started, orange while it is working, green when it is ready, grey when the constructible does not pass through it;</li><li>a kit chip (for example <em>13 parts left</em> or <em>Kitted parts</em>) when your company tracks kits;</li><li>the delivery state once the constructible has been loaded on a rack.</li></ul><p>A red chip with a date marks a constructible that is late. Multipanel groups have a row of their own, placed just before their first panel.</p><h2 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;Layout&quot;">​</a></h2><p><img src="'+n+'" alt="The production viewer in the Extended view"></p><ol><li>The account button. It shows who is working. See <a href="#who-is-working">Who is working</a>.</li><li>The mode toggle.</li><li>The list filter. See <a href="#working-by-project">Working by project</a>.</li><li>The open constructible, with one chip per station.</li><li>The zones and the 3D tools. See <a href="#_3d-model">3D Model</a>.</li><li>Front and back view.</li><li><strong>3D</strong> and the drawings of the constructible. See <a href="#technical-drawings">Technical Drawings</a>.</li><li>Switch between the Extended and the Standard view.</li><li>The toolbar.</li><li>The checklist of your station. See <a href="#checklist">Checklist</a>.</li><li>The part lists and the data of the part you picked.</li></ol><p>The Viewer uses a three-panel layout:</p><table><thead><tr><th>Panel</th><th>Content</th></tr></thead><tbody><tr><td><strong>Left</strong></td><td>3D model or technical drawing (PDF)</td></tr><tr><td><strong>Center</strong></td><td>Vertical toolbar with action buttons</td></tr><tr><td><strong>Right</strong></td><td>Extended view only: the checklist on top, then the part lists and part data when the left panel shows the 3D model, or detail drawings and documents when it shows a drawing</td></tr></tbody></table><p>There are two views, switched with the <strong>Extended</strong> / <strong>Standard</strong> button at the top of the toolbar:</p><ul><li><strong>Extended</strong> — All three panels. The right panel shows the panel checklist at the top and the usual drawing underneath, so a worker can tick tasks off with the drawing in front of them. The checklist button is not in the toolbar in this view: it would only open the same tasks in a dialog.</li><li><strong>Standard</strong> — Left panel + toolbar. The drawing takes all the width, and the checklist goes back to being a button in the toolbar. Detail drawings and documents open full screen from buttons at the bottom of the toolbar.</li></ul><p>Extended is the default on big screens, standard on phones and small tablets, and your choice is remembered on that device. Both views are available on any screen. On a phone the toolbar becomes a bar at the bottom of the screen: tap the arrow to open it and see all the buttons.</p><h2 id="_3d-model" tabindex="-1">3D Model <a class="header-anchor" href="#_3d-model" aria-label="Permalink to &quot;3D Model&quot;">​</a></h2><p><img src="'+i+'" alt="The 3D model and its controls"></p><ol><li>The zones: tap one to show or hide it.</li><li>Measurement.</li><li>Clipping plane.</li><li>Recenter.</li><li>Look at the panel from the front or from the back.</li></ol><h3 id="controls" tabindex="-1">Controls <a class="header-anchor" href="#controls" aria-label="Permalink to &quot;Controls&quot;">​</a></h3><ul><li><strong>Rotate</strong> — Click and drag to rotate the model.</li><li><strong>Zoom</strong> — Use the scroll wheel.</li><li><strong>Pan</strong> — Right-click and drag to move around.</li><li><strong>Recenter</strong> — Click the recenter button at the top right to reset the view.</li><li><strong>Front / Back</strong> — Buttons under the top-right controls to look at the panel from the front or from the back.</li></ul><h3 id="selecting-parts" tabindex="-1">Selecting Parts <a class="header-anchor" href="#selecting-parts" aria-label="Permalink to &quot;Selecting Parts&quot;">​</a></h3><p>Click any part in the 3D model to select it. In the Extended view the right panel shows its data, including:</p><ul><li>Zone, reference and material, as chips at the top</li><li>Dimensions (width, height, length, thickness), finish and comment</li><li>Branch, category and the custom part classes that recognised it</li><li>IFC properties and property sets</li><li>Creation date and revision number</li></ul><p>Click <strong>Part data</strong> to fold or unfold the details. If the part has part drawings, they are shown under <strong>Drawing</strong>: tap one to open it full screen, or tap <strong>3d</strong> to turn the part around in 3D.</p><h3 id="zone-selection" tabindex="-1">Zone Selection <a class="header-anchor" href="#zone-selection" aria-label="Permalink to &quot;Zone Selection&quot;">​</a></h3><p>Use the zone toggle buttons at the top right to show or hide specific zones of the constructible. This is useful for focusing on a specific area during production. When a constructible opens, the zones assigned to your station are selected; if your station has none, all zones are.</p><p>For modules, you can also filter by sub-assembly using the assembly dropdown.</p><h3 id="advanced-tools" tabindex="-1">Advanced Tools <a class="header-anchor" href="#advanced-tools" aria-label="Permalink to &quot;Advanced Tools&quot;">​</a></h3><ul><li><strong>Measurement</strong> — Click the ruler button, then double-click on the model to place the points of a measurement. Click the ruler again to go back to selecting parts.</li><li><strong>Clipping Plane</strong> — Click the clipping button (next to the ruler), then double-click a face of the model to place a cutting plane that reveals the interior structure. Click the button again to remove the plane.</li></ul><p><img src="'+r+'" alt="A clipping plane across the panel"></p><ol><li>The clipping button turns orange while the plane is on.</li><li>The plane, placed on the face you double-clicked. The arrow shows the side that is cut away.</li></ol><h2 id="technical-drawings" tabindex="-1">Technical Drawings <a class="header-anchor" href="#technical-drawings" aria-label="Permalink to &quot;Technical Drawings&quot;">​</a></h2><p><img src="'+l+'" alt="A drawing open in the left panel"></p><ol><li>The pages of a drawing with several.</li><li>The drawing buttons. The lighter one was generated by produuz.it.</li><li>Recenter.</li></ol><p>The left panel can switch between the 3D model and technical drawings (PDFs). Use the buttons at the bottom of the left panel: <strong>3D</strong> for the model, and one button per drawing.</p><ul><li>When your station has drawings assigned, only those are listed, and the station&#39;s default drawing opens on its own.</li><li>Drawings generated automatically by produuz.it have a lighter button than uploaded ones.</li><li>Multi-page drawings show arrows and a page counter to move between pages.</li><li>The recenter button at the top right resets the zoom.</li></ul><h2 id="bill-of-materials-bom" tabindex="-1">Bill of Materials (BOM) <a class="header-anchor" href="#bill-of-materials-bom" aria-label="Permalink to &quot;Bill of Materials (BOM)&quot;">​</a></h2><p>When the left panel shows the 3D model, the right panel starts with <strong>Part lists</strong> for the current assembly: one button per branch (<strong>Timber</strong>, <strong>Plate</strong> and your custom branches). While the model is still being analysed, a message says to wait a few minutes.</p><h3 id="part-list" tabindex="-1">Part List <a class="header-anchor" href="#part-list" aria-label="Permalink to &quot;Part List&quot;">​</a></h3><p>Tap a branch to open its <strong>Bill of Materials</strong> table. Parts with the same reference, material, comment and finish share one row, with these columns: <strong>REF</strong> (with the part category chips), <strong>Material</strong>, <strong>Count</strong>, <strong>Size</strong>, <strong>Length</strong>, <strong>Comment</strong>, <strong>Finish</strong> and <strong>Zone</strong>. <strong>Select</strong> highlights those parts in the 3D model.</p><p><img src="'+h+'" alt="The Bill of Materials of the timber branch"></p><ol><li>The reference and the category of the part.</li><li><strong>Select</strong> highlights these parts in the 3D model.</li></ol><h3 id="unknown-parts" tabindex="-1">Unknown Parts <a class="header-anchor" href="#unknown-parts" aria-label="Permalink to &quot;Unknown Parts&quot;">​</a></h3><p>Next to the branch buttons, lighter buttons list the parts found in the model file but not in the database, per branch, plus an <strong>unknown</strong> button for the rest. This helps identify parts that may need to be added to the system.</p><h3 id="part-drawings" tabindex="-1">Part Drawings <a class="header-anchor" href="#part-drawings" aria-label="Permalink to &quot;Part Drawings&quot;">​</a></h3><p>When a part is selected, its part drawings are shown under the part data. See <a href="#selecting-parts">Selecting Parts</a>.</p><h2 id="production-features" tabindex="-1">Production Features <a class="header-anchor" href="#production-features" aria-label="Permalink to &quot;Production Features&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Production features are only available in <strong>Production</strong> mode (not in Design mode).</p></div><h3 id="checklist" tabindex="-1">Checklist <a class="header-anchor" href="#checklist" aria-label="Permalink to &quot;Checklist&quot;">​</a></h3><p><img src="'+c+'" alt="The checklist of one station"></p><ol><li>Who is working. See <a href="#who-is-working">Who is working</a>.</li><li>The station tabs. A green check marks a finished station.</li><li>A ticked task, with who ticked it and when.</li><li>A task that needs a picture: the photos taken so far, the camera button and the browse button.</li><li>A task with a form. The red dot means the form is still empty.</li><li>A task that needs a QR code.</li><li><strong>Station job completed</strong>, enabled once every task is ticked.</li></ol><p>The checklist shows the production progress for the current constructible at the selected station. In the Standard view it opens from the <strong>Tasks</strong> button in the toolbar; in the Extended view it sits at the top of the right panel.</p><ul><li><strong>Tasks button</strong> — Says <em>Not started</em>, <em>Paused</em>, <em>Ready</em>, or how many tasks are done (for example <code>3 of 8</code>). The bar under it is red when the panel is not started, orange while it is in progress, and fills green as tasks are ticked. Under the button, a scrolling line shows your station and the next task.</li><li><strong>Header</strong> — The station tabs (a green check marks a finished station) and the names of who is working. See <a href="#who-is-working">Who is working</a>.</li><li><strong>Task list</strong> — Each task has a checkbox, and may require: <ul><li>QR code scanning</li><li>A picture (see below)</li><li>Filling a custom form</li><li>Reviewing associated documents</li></ul></li></ul><p><strong>Tasks that need a picture</strong></p><p>The task row has a <strong>camera button</strong> and a <strong>browse button</strong>, on every device.</p><ul><li>On an Android tablet or phone, the camera button opens the device&#39;s own camera app: take the photo, confirm, and you are back on the checklist.</li><li>On a computer or a Windows tablet it opens the camera in a small window — one click to open, one to shoot.</li><li>The browse button picks a photo you already have. On a computer you can also drag files onto the row or paste a screenshot into it.</li></ul><div class="tip custom-block"><p class="custom-block-title">The camera button opens the gallery instead?</p><p>Some companies manage their tablets with a policy that blocks the camera app. The app cannot tell that apart from a working camera, so it asks and the device answers with the photo gallery. An admin can switch on <strong>Avoid native camera in viewer</strong> under the <strong>Settings</strong> button of the company page, and the app will take the picture itself instead of asking the device.</p></div><ul><li>The photo is stored <strong>exactly as the camera took it</strong>, at full resolution. It is the quality record of the panel, so nothing is shrunk or re-compressed.</li><li><strong>The task ticks itself</strong> when the photo is stored, as long as nothing else is missing — a form still to fill or a QR still to scan keeps it unticked. You can always untick it.</li><li>The photos stay visible <strong>after</strong> the task is ticked, as thumbnails. Tap one to see the picture full size. <strong>Clean</strong> removes them. A photo taken before this feature existed gets its thumbnail the first time somebody opens the panel, so an old panel with many pictures fills in over a couple of visits.</li><li>Each thumbnail says <strong>who uploaded it</strong> when you hover or press it. See: <a href="/guide/reports/quality_control/">Quality Control Report</a></li><li>If the upload fails you get a message, the thumbnail disappears and the task is <strong>not</strong> ticked, so a missing photo can never look like a stored one.</li></ul><p><strong>Actions:</strong></p><p>Tasks can only be ticked once the panel and the station are started. Depending on the state, the checklist shows one of these:</p><ul><li><strong>Start production</strong> — The panel has not been started yet. This starts it at your station. If your company tracks kits and parts are missing, a warning (<em>The kit is not complete</em>) lets you <strong>Start anyway</strong> or <strong>Cancel</strong>.</li><li><strong>Force start station</strong> — Shown instead when you are at a later station and the previous stations are not finished. After you confirm, the previous stations are marked as ready and yours is started.</li><li><strong>Start station</strong> — The panel is under way, but your station has not started it yet.</li><li><strong>Resume</strong> — The panel is paused.</li><li><strong>Pause</strong> — Temporarily stop work.</li><li><strong>Station job completed</strong> — Mark the station as done (enabled when all tasks are checked). At the last station of the line the button reads <strong>Panel ready</strong> and finishes the constructible.</li></ul><p>When the station is done, the checklist shows <em>Job for your station is completed</em>.</p><h3 id="multiwall-checklist" tabindex="-1">Multiwall Checklist <a class="header-anchor" href="#multiwall-checklist" aria-label="Permalink to &quot;Multiwall Checklist&quot;">​</a></h3><p>When you open a Multipanel Group in the viewer, the toolbar shows a group <strong>Tasks</strong> button instead of the per-panel one. It gathers the checklist of every panel of the group at the currently selected station, so a worker can drive the whole multiwall from a single screen.</p><ul><li><strong>Progress</strong> — The button shows how many panels of the group are loaded (for example <code>4 / 5</code>) and the combined progress for the current station across all of them.</li><li><strong>Start</strong> — If some panels are not started at this station, a banner says how many and offers <strong>Start all panels</strong>.</li><li><strong>Tasks</strong> — Each task has a heading with a chip that shows on how many panels it is ticked (<code>3 / 5</code>). Under it there is one row per panel, labelled with the panel name, so each panel can be ticked, photographed or filled in on its own.</li><li><strong>Check all</strong> — Simple tasks (no picture, form or QR field) have a <strong>Check all</strong> button that ticks the task on every panel at once.</li><li><strong>Station switcher</strong> — The station tabs in the dialog header move the whole group between stations.</li><li><strong>Station job completed</strong> / <strong>Panel ready</strong> — Enabled once every task is ticked on every panel.</li></ul><p><img src="'+d+'" alt="The checklist of a multipanel group"></p><ol><li>How many panels of the group are loaded.</li><li>Some panels are not started at this station: <strong>Start all panels</strong> starts them.</li><li>A simple task: one row per panel, and <strong>Check all</strong> ticks it on every panel.</li><li>A task with a picture is done panel by panel.</li></ol><h3 id="station-switching" tabindex="-1">Station Switching <a class="header-anchor" href="#station-switching" aria-label="Permalink to &quot;Station Switching&quot;">​</a></h3><p>Tap the station tabs at the top of the checklist, or open the account button at the top of the left menu and choose <strong>Change Station</strong> to pick any station of any line. For production users the tabs only allow the previous stations, and the next one once your station is ready. If you open a station whose previous stations are not finished, the checklist offers <strong>Force start station</strong> (see above).</p><h3 id="issues" tabindex="-1">Issues <a class="header-anchor" href="#issues" aria-label="Permalink to &quot;Issues&quot;">​</a></h3><p><img src="'+g+'" alt="The Note button: a new issue"></p><ol><li>The constructible the issue is attached to, and the engineering contact of the project.</li><li><em>Production Issue</em> or <em>Quality Control Issue</em>.</li><li>Make the issue visible in the viewer for every worker.</li><li>Also send it to chosen colleagues in the chat.</li><li>Pictures and files, with the camera and browse buttons.</li><li>Add the data of the parts selected in the 3D model to the text.</li></ol><p>Two buttons in the toolbar deal with issues:</p><ul><li><strong>Note</strong> — Create a new issue for this constructible. Pick a <strong>Category</strong> (<em>Production Issue</em> or <em>Quality Control Issue</em>), enter a <strong>Title</strong> and <strong>Content</strong>, and add pictures or files with the camera and browse buttons. <strong>Attach part info</strong> adds the data of the parts selected in the 3D model to the text. <strong>Send message to</strong> sends the issue to chosen colleagues in the chat. Tick <strong>Show in viewer to everybody.</strong> to make the issue visible in the viewer for every worker.</li><li><strong>Issues</strong> — Lists the production issues of this constructible that were marked <em>Show in viewer to everybody.</em> The badge shows how many there are. Tap one to see its text, category, status, user, creation date, whether it is solved, and its pictures.</li></ul><h3 id="qr-code" tabindex="-1">QR Code <a class="header-anchor" href="#qr-code" aria-label="Permalink to &quot;QR Code&quot;">​</a></h3><p>Click the QR button to display a QR code for the current constructible, and <strong>Print</strong> to print it. It can be attached to the physical item for quick identification on the shop floor.</p><h3 id="rfid-tag" tabindex="-1">RFID Tag <a class="header-anchor" href="#rfid-tag" aria-label="Permalink to &quot;RFID Tag&quot;">​</a></h3><p>Click the RFID button to register an RFID tag code for the current constructible. You can type the code, or press <strong>Scan QR</strong> to read the QR code printed on the tag with the camera.</p><h3 id="rack-logistics" tabindex="-1">Rack / Logistics <a class="header-anchor" href="#rack-logistics" aria-label="Permalink to &quot;Rack / Logistics&quot;">​</a></h3><p>The <strong>Rack</strong> button only appears when the constructible is on a rack load. It turns green and reads <strong>In rack</strong> once the constructible is loaded. It opens the <strong>Rack Arrangement</strong>:</p><ul><li>the rack load, its rack, the position of this constructible and how many panels are loaded;</li><li>a warning when the panel is not finished yet, or when other panels must go on the rack before it;</li><li>a drawing of the rack and the list of panels on the load, in loading order;</li><li><strong>Mark loaded</strong> and <strong>Mark not loaded</strong> at the bottom.</li></ul><h2 id="who-is-working" tabindex="-1">Who is working <a class="header-anchor" href="#who-is-working" aria-label="Permalink to &quot;Who is working&quot;">​</a></h2><p>Several people often share one tablet account. So that the records name the person and not the tablet, each person has an <strong>alias</strong> (for example <code>JAN</code>), and the account keeps a list of the people who may work under it (<strong>Production employees</strong>). Both are set in <strong>Company settings → User accounts</strong>.</p><p>To say who is at the station right now:</p><ol><li>Open the account button at the top of the left menu and choose <strong>Change employees</strong>, or tap the names in the checklist header.</li><li>The <strong>Select employees</strong> dialog shows one card per person, with the alias, the name and your company&#39;s own id for that person. The card of the account itself has a key icon and says <em>this account</em>.</li><li>Tap every person who is working. Tap again to deselect. <strong>Clean</strong> deselects everybody.</li><li>Press <strong>Save</strong>.</li></ol><p><img src="'+p+'" alt="The Select employees dialog"></p><ol><li>The account itself: pick it when the work should be filed under the account.</li><li>A selected person.</li></ol><p><strong>Change employees</strong> only appears when more than one person can work under the account. With a single person there is nothing to choose, and that person is used automatically. If nobody is selected, the work is recorded under the account itself.</p><p>Once saved, the aliases are shown:</p><ul><li>on the account button, in orange, instead of the username (<code>JAN · PIET</code>, or <code>JAN +2</code> for more than two people);</li><li>in the checklist header, as chips (in the Extended view, one chip with the number of people);</li><li>on every ticked task, with the time: <code>JAN · PIET · 10:02</code>;</li><li>on each picture, as <em>Uploaded by</em>.</li></ul><p>The same names appear in the <a href="/guide/reports/quality_control/">Quality Control Report</a> and in the Production Proof card of the constructible.</p><h2 id="specifications-documents" tabindex="-1">Specifications &amp; Documents <a class="header-anchor" href="#specifications-documents" aria-label="Permalink to &quot;Specifications &amp; Documents&quot;">​</a></h2><ul><li><strong>Spec</strong> — When the constructible has a specification, a <strong>Spec</strong> button appears in the toolbar (or a list of buttons, one per specification). Press and hold it to see the document; release to close it.</li><li><strong>DETS / DOCS</strong> — The button at the bottom of the toolbar switches the files offered for this constructible between detail drawings (<strong>DETS</strong>) and documents (<strong>DOCS</strong>). In documents mode the Bill of Materials files generated for it are listed too. In the Extended view the files open in the right panel; in the Standard view they open full screen.</li></ul>',111),w=[m];function f(b,k,y,v,T,P){return t(),o("div",null,w)}const x=e(u,[["render",f]]);export{q as __pageData,x as default};
